// Offline scene tile builder; no off-mesh connections and no source geometry mutation.
#include "tiled_recast_builder.h"
#include <array>
#include <limits>
#include <algorithm>
#include <iomanip>
struct Blob {unsigned char* data;int size,polygons,tx,ty;float cell;};
int main(int argc,char**argv){try{
 require(argc==9,"input outputdir mode tileWorld coarseXmin coarseXmax coarseZmin coarseZmax");std::string input=argv[1],root=argv[2],mode=argv[3];require(mode=="coarse"||mode=="fine"||mode=="mixed","mode");float world=std::stof(argv[4]);require(world==2,"fixed2m tiles");float patch[4];for(int i=0;i<4;++i)patch[i]=std::stof(argv[5+i]);
 std::ifstream in(input,std::ios::binary);int nv=0,nt=0;in.read((char*)&nv,4);in.read((char*)&nt,4);require(in&&nv>0&&nt>0&&nv<20000000&&nt<20000000,"input header");Geometry g;g.v.resize(size_t(nv)*3);g.t.resize(size_t(nt)*3);in.read((char*)g.v.data(),g.v.size()*4);in.read((char*)g.t.data(),g.t.size()*4);require(in&&in.peek()==std::char_traits<char>::eof(),"input length");float lo[3],hi[3];for(int k=0;k<3;++k){lo[k]=std::numeric_limits<float>::max();hi[k]=-lo[k];}for(int i=0;i<nv;++i)for(int k=0;k<3;++k){float x=g.v[3*i+k];require(std::isfinite(x),"nonfinite vertex");lo[k]=std::min(lo[k],x);hi[k]=std::max(hi[k],x);}for(int index:g.t)require(index>=0&&index<nv,"index bounds");
 std::vector<std::array<float,4>> boxes(nt);for(int i=0;i<nt;++i){float a=g.v[3*g.t[3*i]],b=a,c=g.v[3*g.t[3*i]+2],d=c;for(int j=1;j<3;++j){float x=g.v[3*g.t[3*i+j]],z=g.v[3*g.t[3*i+j]+2];a=std::min(a,x);b=std::max(b,x);c=std::min(c,z);d=std::max(d,z);}boxes[i]={a,b,c,d};}
 int nx=int(ceilf((hi[0]-lo[0])/world)),nz=int(ceilf((hi[2]-lo[2])/world));require(nx>0&&nz>0&&nx*nz<=4096,"tile grid bound");std::vector<Blob> blobs;std::ofstream tiles(root+"/tiles.jsonl");tiles<<std::setprecision(12);int coarseTiles=0,fineTiles=0,maxPolys=0;
 for(int tz=0;tz<nz;++tz)for(int tx=0;tx<nx;++tx){float xmin=lo[0]+tx*world,xmax=lo[0]+(tx+1)*world,zmin=lo[2]+tz*world,zmax=lo[2]+(tz+1)*world;bool coarse=mode=="coarse"||(mode=="mixed"&&xmax>=patch[0]&&xmin<=patch[1]&&zmax>=patch[2]&&zmin<=patch[3]);TileSpec spec;spec.tx=tx;spec.ty=tz;spec.world=world;spec.cell=coarse?.05f:.025f;for(int k=0;k<3;++k)spec.origin[k]=lo[k];spec.ymax=hi[1];auto cfg=tileConfig(spec);Geometry selected;selected.v=g.v;
 for(int i=0;i<nt;++i){const auto& b=boxes[i];if(b[1]<cfg.bmin[0]||b[0]>cfg.bmax[0]||b[3]<cfg.bmin[2]||b[2]>cfg.bmax[2])continue;selected.t.insert(selected.t.end(),g.t.begin()+i*3,g.t.begin()+i*3+3);}
 int size=0,polygons=0;unsigned char* data=nullptr;if(!selected.t.empty())data=makeTile(selected,spec,size,polygons);
 if(data){blobs.push_back({data,size,polygons,tx,tz,spec.cell});maxPolys=std::max(maxPolys,polygons);if(coarse)++coarseTiles;else ++fineTiles;}
 tiles<<"{\"x\":"<<tx<<",\"z\":"<<tz<<",\"cell_size\":"<<spec.cell<<",\"cell_height\":0.05,\"region_area_voxels\":"<<cfg.minRegionArea<<",\"border_voxels\":"<<cfg.borderSize<<",\"detail_sample_distance_m\":"<<cfg.detailSampleDist<<",\"contour_error_voxels\":"<<cfg.maxSimplificationError<<",\"input_triangles\":"<<selected.t.size()/3<<",\"polygons\":"<<polygons<<",\"bytes\":"<<size<<"}\n";tiles.flush();
 }
 require(!blobs.empty(),"no walkable tiles");dtNavMeshParams params{};for(int k=0;k<3;++k)params.orig[k]=lo[k];params.tileWidth=world;params.tileHeight=world;params.maxTiles=int(blobs.size());params.maxPolys=maxPolys;std::unique_ptr<dtNavMesh,void(*)(dtNavMesh*)> nav(dtAllocNavMesh(),dtFreeNavMesh);require(dtStatusSucceed(nav->init(&params)),"navmesh capacity");for(auto& b:blobs){auto status=nav->addTile(b.data,b.size,DT_TILE_FREE_DATA,0,nullptr);if(dtStatusFailed(status))throw std::runtime_error("add real tile");b.data=nullptr;}
 save(nav.get(),root+"/scene.navmesh");std::ofstream out(root+"/input-copy.bin",std::ios::binary);out.write((char*)&nv,4);out.write((char*)&nt,4);out.write((char*)g.v.data(),g.v.size()*4);out.write((char*)g.t.data(),g.t.size()*4);require(bool(out),"source copy");std::ofstream meta(root+"/native-summary.json");meta<<std::setprecision(12)<<"{\"mode\":\""<<mode<<"\",\"tile_world_m\":"<<world<<",\"grid_x\":"<<nx<<",\"grid_z\":"<<nz<<",\"active_tiles\":"<<blobs.size()<<",\"coarse_tiles\":"<<coarseTiles<<",\"fine_tiles\":"<<fineTiles<<",\"pool_slots\":"<<params.maxTiles<<",\"max_polygons\":"<<maxPolys<<",\"source_vertices\":"<<nv<<",\"source_triangles\":"<<nt<<",\"origin\":["<<lo[0]<<","<<lo[1]<<","<<lo[2]<<"],\"offmesh_connections\":0}\n";std::cout<<"TILED_SCENE_COMPLETE "<<blobs.size()<<"\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
